#!/usr/bin/env python3
"""Compare the settled nested-KWin screenshots of this run (evidence/phase2/*.png, regenerated by
the unchanged kwin_gui test through the AMENDED renderer) with the Phase 2 baseline copy
(evidence/phase3/phase2-baseline/*.png, taken before the ownership amendment).

Writes evidence/phase3/screenshot-compare.txt. Fails closed on a missing/extra file, a size
change, or a changed-pixel share above THRESHOLD; every bounding box of change is listed so the
differences can be explained (live clock text, terminal prompt/cursor) rather than ignored.
"""
from pathlib import Path
import sys

import numpy as np
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / "evidence/phase3/phase2-baseline"
NOW = ROOT / "evidence/phase2"
OUT = ROOT / "evidence/phase3/screenshot-compare.txt"
CHANNEL_TOLERANCE = 12  # per-channel difference ignored as anti-aliasing / compositing noise
THRESHOLD = 0.01  # share of pixels allowed to differ beyond the tolerance


def main():
    names = sorted(p.name for p in BASE.glob("*.png"))
    if not names:
        raise SystemExit("FAIL: no Phase 2 baseline screenshots")
    now_names = sorted(p.name for p in NOW.glob("*.png"))
    if names != now_names:
        raise SystemExit(f"FAIL: screenshot sets differ: {sorted(set(names) ^ set(now_names))}")
    lines = [f"{'file':44} {'size':>10} {'changed px':>11} {'share':>8}  bbox of change"]
    worst = 0.0
    for name in names:
        a = np.asarray(Image.open(BASE / name).convert("RGBA"), dtype=np.int16)
        b = np.asarray(Image.open(NOW / name).convert("RGBA"), dtype=np.int16)
        if a.shape != b.shape:
            raise SystemExit(f"FAIL: {name} size changed {a.shape} -> {b.shape}")
        changed = np.abs(a - b).max(axis=2) > CHANNEL_TOLERANCE
        count = int(changed.sum())
        share = count / changed.size
        worst = max(worst, share)
        if count:
            ys, xs = np.where(changed)
            bbox = f"x{xs.min()}..{xs.max()} y{ys.min()}..{ys.max()}"
        else:
            bbox = "-"
        lines.append(f"{name:44} {a.shape[1]}x{a.shape[0]:<5} {count:>11} {share:>8.4%}  {bbox}")
    lines.append(f"worst changed share: {worst:.4%} (threshold {THRESHOLD:.2%}, per-channel tolerance {CHANNEL_TOLERANCE})")
    OUT.write_text("\n".join(lines) + "\n")
    print("\n".join(lines))
    if worst > THRESHOLD:
        raise SystemExit("FAIL: screenshot drift above threshold; inspect the images")
    print("PASS: settled screenshots match the Phase 2 baseline within threshold")


if __name__ == "__main__":
    sys.exit(main())
